import { mkdtempSync, rmSync } from "node:fs";
import { join } from "node:path";

export async function createWorkload(source: string, size: number, strategyKind: "static" | "custom", diagnostics: boolean) {
  const api = await import(`${source}/index.ts`);
  const root = mkdtempSync(join(import.meta.dir, "run-output-"));
  const checks = Array.from({ length: size }, (_, index) => ({
    checkId: `check-${String(index).padStart(5, "0")}`,
    displayName: `Check ${index}`,
    options: { index, payload: Array.from({ length: 8 }, (_, offset) => ({ offset, enabled: true })) },
    admissionPriority: index % 3,
    resourceClaims: { worker: 1 },
    ...(index % 8 === 7 ? { observes: [`check-${String(index - 1).padStart(5, "0")}`] } : {}),
    execute: async () => ({ status: "passed", data: { index } })
  }));
  const groups = Array.from({ length: Math.ceil(size / 16) }, (_, index) => ({
    checkId: `group-${index}`,
    displayName: `Group ${index}`,
    maxParallel: 4,
    checks: checks.slice(index * 16, index * 16 + 16)
  }));
  const definition = api.defineConfig({
    checks: groups,
    scheduler: {
      maxParallel: 8,
      resourceCapacities: { worker: 8 },
      ...(strategyKind === "static" ? {} : {
        admissionPolicy: {
          kind: "custom",
          strategy: {
            kind: "prepared",
            prepare() {
              return {
                decide(context: any) {
                  const candidate = context.candidates.find((entry: any) => entry.canAdmit);
                  return candidate === undefined ? { kind: "wait" } : { kind: "select", taskId: candidate.taskId };
                }
              };
            }
          }
        }
      })
    },
    outputs: {
      diagnosticLogging: { enabled: diagnostics, directory: join(root, "logs") },
      machinePublication: { enabled: false },
      progressRendering: { enabled: false }
    }
  });
  return {
    async run() {
      const result = await api.run(definition, { projectRoot: root });
      if (result.kind !== "completed" || result.aggregate !== "passed" || result.snapshot.checks.length !== size) {
        throw new Error(`workload semantic failure: ${result.kind}`);
      }
      return result;
    },
    close() { rmSync(root, { recursive: true, force: true }); }
  };
}

import { resolve } from "node:path";
import { createWorkload } from "./workload.ts";

const [variant, sizeText, strategyText, outputText, mode = "time", batch = "unbatched", slot = "0"] = process.argv.slice(2);
if (!variant || !sizeText || !strategyText || !outputText) throw new Error("missing workload arguments");
const size = Number(sizeText);
const strategy = strategyText === "custom" ? "custom" : "static";
const diagnostics = outputText === "diagnostics";
const counts = { parse: 0, resolve: 0, materialize: 0, plan: 0, prepare: 0 };
(globalThis as any).__preparedFactsCounts = counts;
const source = resolve(import.meta.dir, "node_modules", variant, "src");
const workload = await createWorkload(source, size, strategy, diagnostics);
const startedAtUtc = new Date().toISOString();
try {
  if (mode === "counts" || mode === "smoke") {
    await workload.run();
    console.log(JSON.stringify({ variant, size, strategy, output: outputText, mode, counts }));
  } else {
    for (let index = 0; index < 3; index += 1) await workload.run();
    const samples: number[] = [];
    for (let index = 0; index < 5; index += 1) {
      const started = performance.now();
      await workload.run();
      samples.push(performance.now() - started);
    }
    const ordered = [...samples].sort((left, right) => left - right);
    console.log(JSON.stringify({
      variant, size, strategy, output: outputText, mode,
      batch, slot: Number(slot), startedAtUtc, endedAtUtc: new Date().toISOString(),
      warmups: 3, samples, medianMs: ordered[2], p95Ms: ordered[4],
      maxRssKb: process.resourceUsage().maxRSS,
      versions: process.versions,
      platform: process.platform, arch: process.arch
    }));
  }
} finally { workload.close(); }
